import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type ReminderHeaderProps = Record<string, any>;

const ReminderHeader: React.FC<ReminderHeaderProps> = ({
  backgroundColor = "#09090b",
  transparentBackground = true,
  durationInSeconds = 6,
  accentColor = "#f43f5e",
  textColor = "#fafafa",
  badgeText = "REMINDER",
  headlineText = "Set Your Alarm!",
  dateText = "Tuesday, March 10th",
  ringIntensity = 5.0,
}) => {

  {/* Load Google Fonts */}
  useFontLoader(["Outfit", "Inter"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Base sizing logic
  const clockSize = Math.min(width, height) * 0.45;
  const contentGap = width * 0.08;

  // --- Animations ---

  // Global entry
  const entranceSpring = spring({
    fps,
    frame,
    config: { damping: 14, mass: 1 },
  });

  // Clock Animations
  const clockScale = interpolate(entranceSpring, [0, 1], [0.5, 1]);
  const clockOpacity = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" });
  
  // Erratic ringing calculation
  const isRingingPhase = frame > 25;
  const rawRing = Math.sin(frame * 1.5) + Math.cos(frame * 2.3);
  const ringAngle = isRingingPhase ? rawRing * ringIntensity : 0;

  // Radiating waves logic
  const waveDuration = 60;
  const waveFrames = [
    Math.max(0, (frame - 30) % waveDuration),
    Math.max(0, (frame - 50) % waveDuration),
  ];

  // Text Entry Animations
  const textDelay = 10;
  
  const badgeSpring = spring({ fps, frame: frame - textDelay, config: { damping: 12 } });
  const badgeY = interpolate(badgeSpring, [0, 1], [40, 0]);
  const badgeOpacity = interpolate(frame - textDelay, [0, 15], [0, 1], { extrapolateRight: "clamp" });

  const headlineSpring = spring({ fps, frame: frame - (textDelay + 5), config: { damping: 12 } });
  const headlineY = interpolate(headlineSpring, [0, 1], [60, 0]);
  const headlineOpacity = interpolate(frame - (textDelay + 5), [0, 15], [0, 1], { extrapolateRight: "clamp" });

  const dateSpring = spring({ fps, frame: frame - (textDelay + 10), config: { damping: 12 } });
  const dateScale = interpolate(dateSpring, [0, 1], [0.8, 1]);
  const dateOpacity = interpolate(frame - (textDelay + 10), [0, 15], [0, 1], { extrapolateRight: "clamp" });

  // Clock hands
  const minuteHandRotation = frame * 4;
  const hourHandRotation = frame * 0.5;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none", overflow: "hidden" }}>
      
      {/* Background Subtle Gradient Glow based on accent */}
      <div style={{
        position: "absolute",
        top: "-50%",
        left: "-20%",
        width: "150%",
        height: "200%",
        background: `radial-gradient(circle at 40% 50%, ${accentColor}1A 0%, transparent 60%)`,
        opacity: interpolate(Math.sin(frame * 0.05), [-1, 1], [0.6, 1]),
        transition: "none",
        pointerEvents: "none"
      }} />

      <div style={{
        display: "flex",
        flexDirection: "row",
        alignItems: "center",
        justifyContent: "center",
        width: "100%",
        height: "100%",
        gap: contentGap,
        padding: `0 ${width * 0.05}px`,
        boxSizing: "border-box",
      }}>
        
        {/* --- LEFT SIDE: ALARM CLOCK --- */}
        <div style={{
          position: "relative",
          width: clockSize,
          height: clockSize,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          opacity: clockOpacity,
          transform: `scale(${clockScale}) rotate(${ringAngle}deg)`,
          transition: "none",
        }}>
          
          {/* Animated Radiating Waves behind the clock */}
          {isRingingPhase && waveFrames.map((wFrame, i) => {
             if (frame < 30 + (i * 20)) return null;
             const wScale = interpolate(wFrame, [0, waveDuration], [1, 2.5]);
             const wOpacity = interpolate(wFrame, [0, waveDuration * 0.2, waveDuration], [0, 0.5, 0]);
             return (
               <div key={`wave-${i}`} style={{
                 position: "absolute",
                 width: clockSize * 0.7,
                 height: clockSize * 0.7,
                 borderRadius: "50%",
                 border: `4px solid ${accentColor}`,
                 opacity: wOpacity,
                 transform: `scale(${wScale})`,
                 transition: "none",
               }} />
             );
          })}

          <svg 
            width="100%" 
            height="100%" 
            viewBox="0 0 100 100" 
            style={{ 
              overflow: "visible", 
              transition: "none",
              position: "relative",
              zIndex: 10
            }}
          >
            {/* Clock Legs */}
            <line x1="30" y1="80" x2="20" y2="95" stroke={textColor} strokeWidth="6" strokeLinecap="round" />
            <line x1="70" y1="80" x2="80" y2="95" stroke={textColor} strokeWidth="6" strokeLinecap="round" />
            
            {/* Top Button / Handle */}
            <line x1="50" y1="15" x2="50" y2="5" stroke={textColor} strokeWidth="6" strokeLinecap="round" />
            <line x1="40" y1="5" x2="60" y2="5" stroke={textColor} strokeWidth="6" strokeLinecap="round" />
            
            {/* Left Bell */}
            <path d="M 22 35 A 16 16 0 0 1 42 16" fill="none" stroke={accentColor} strokeWidth="6" strokeLinecap="round" />
            <circle cx="22" cy="35" r="3" fill={accentColor} />
            
            {/* Right Bell */}
            <path d="M 78 35 A 16 16 0 0 0 58 16" fill="none" stroke={accentColor} strokeWidth="6" strokeLinecap="round" />
            <circle cx="78" cy="35" r="3" fill={accentColor} />

            {/* Main Body Background */}
            <circle cx="50" cy="50" r="35" fill={backgroundColor} stroke="none" />
            
            {/* Outer Body Stroke */}
            <circle cx="50" cy="50" r="35" fill="none" stroke={textColor} strokeWidth="6" />
            
            {/* Inner Clock Face Dashes */}
            <circle cx="50" cy="50" r="28" fill="none" stroke={textColor} strokeWidth="3" strokeDasharray="1 13.66" strokeLinecap="round" opacity={0.5} />

            {/* Hands Wrapper for Transforms */}
            <g style={{ transformOrigin: "50px 50px", transition: "none" }}>
              {/* Hour Hand */}
              <g style={{ transform: `rotate(${hourHandRotation}deg)`, transformOrigin: "50px 50px", transition: "none" }}>
                <line x1="50" y1="50" x2="50" y2="30" stroke={accentColor} strokeWidth="6" strokeLinecap="round" />
              </g>
              {/* Minute Hand */}
              <g style={{ transform: `rotate(${minuteHandRotation}deg)`, transformOrigin: "50px 50px", transition: "none" }}>
                <line x1="50" y1="50" x2="50" y2="22" stroke={textColor} strokeWidth="4" strokeLinecap="round" />
              </g>
              {/* Center Dot */}
              <circle cx="50" cy="50" r="5" fill={textColor} />
            </g>
          </svg>
        </div>

        {/* --- RIGHT SIDE: TYPOGRAPHY --- */}
        <div style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
          justifyContent: "center",
          maxWidth: width * 0.45,
          transition: "none",
        }}>
          
          {/* Badge */}
          {badgeText && (
            <div style={{
              opacity: badgeOpacity,
              transform: `translateY(${badgeY}px)`,
              fontFamily: "Inter, sans-serif",
              fontWeight: 700,
              fontSize: height * 0.025,
              letterSpacing: "0.15em",
              color: accentColor,
              textTransform: "uppercase",
              marginBottom: height * 0.02,
              transition: "none",
            }}>
              {badgeText}
            </div>
          )}

          {/* Headline */}
          <div style={{
            opacity: headlineOpacity,
            transform: `translateY(${headlineY}px)`,
            fontFamily: "Outfit, sans-serif",
            fontWeight: 800,
            fontSize: height * 0.09,
            lineHeight: 1.1,
            color: textColor,
            marginBottom: height * 0.05,
            transition: "none",
          }}>
            {headlineText}
          </div>

          {/* Date Pill */}
          <div style={{
            opacity: dateOpacity,
            transform: `scale(${dateScale})`,
            backgroundColor: accentColor,
            color: "#ffffff",
            fontFamily: "Inter, sans-serif",
            fontWeight: 600,
            fontSize: height * 0.045,
            padding: `${height * 0.025}px ${width * 0.03}px`,
            borderRadius: height * 0.06,
            boxShadow: `0px ${height * 0.01}px ${height * 0.03}px ${accentColor}4D`,
            transition: "none",
            transformOrigin: "left center"
          }}>
            {dateText}
          </div>

        </div>

      </div>
    </AbsoluteFill>
  );
};

export default ReminderHeader;